<template>
  <section id="analysis-progress" class="analysis-progress" :class="{complete:flow.complete,stopped:flow.stopped,compact}" aria-label="Analysis progress">
    <header class="progress-heading">
      <div><p class="progress-label"><span class="connection-dot" :class="connection.state"></span>{{ connection.label }}<span class="elapsed">{{ elapsed }} {{ run.reassessed_from_run_id?'this reassessment':run.resumed_from_run_id?'this continuation':flow.complete||flow.stopped?'this run':'elapsed' }}</span></p><h2>{{ flow.title }}</h2><p v-if="!compact" class="progress-explanation">{{ flow.detail }}</p><p v-if="flow.reuse&&!compact" class="reuse-summary">{{ run.reassessed_from_run_id?'The completed discussion was reused for this assessment.':'This continuation reuses earlier saved work.' }}</p></div>
      <button v-if="flow.complete" class="result-button" @click="$emit('result')">{{ hasPaths?'Review the conditions':'Review the assessment' }}<ResearchIcon name="arrow"/></button>
    </header>
    <template v-if="!flow.complete">
      <div v-if="flow.current.progress" class="current-count" aria-live="polite" aria-atomic="true"><strong>{{ flow.current.progress.value }} <span>/ {{ flow.current.progress.total }} {{ flow.current.progress.unit }}</span></strong><progress :value="flow.current.progress.value" :max="flow.current.progress.total" :aria-label="flow.current.progress.unit"></progress></div>
      <p v-if="run.status==='running'" class="save-status">{{ updateLabel }}<span v-if="connection.state==='reconnecting'"> Showing the last saved state; progress updates will retry automatically.</span><span v-else> Responses appear when each request or batch finishes.</span></p>
    </template>
    <slot name="agents" />
    <details class="process-details" :open="processExpanded" @toggle="processExpanded=$event.target.open">
      <summary>{{ flow.complete?'See how this assessment was made':showActivity?'Stages and saved activity':'Analysis stages' }}</summary>
      <div class="process-content">
        <ol class="stage-list" aria-label="Analysis stages"><li v-for="(stage,index) in flow.steps" :key="stage.id" :class="stage.state" :aria-current="stage.state==='active'||stage.state==='stopped'?'step':undefined"><span class="stage-number"><svg v-if="stage.state==='done'" viewBox="0 0 16 16" aria-hidden="true"><path d="m3 8 3 3 7-7"/></svg><template v-else>{{ index+1 }}</template></span><strong>{{ stage.label }}</strong><small>{{ stateLabel(stage.state) }}</small></li></ol>
        <div v-if="flow.current.id==='discussion'&&!flow.complete" class="phase-list" aria-label="Trader discussion rounds"><div v-for="phase in flow.phases" :key="phase.key"><span>{{ phase.label }}</span><strong>{{ phase.count }}<small v-if="phase.total"> / {{ phase.total }}</small></strong></div></div>
        <div class="activity-layout" :class="{'without-activity':!showActivity}">
          <section v-if="showActivity" class="saved-activity" aria-label="Saved agent activity"><div class="activity-heading"><h3>{{ flow.complete?'Recent saved activity':'Latest saved activity' }}</h3><button v-if="(run.status==='running'||feedPaused)&&activity.length" @click="toggleFeed">{{ feedPaused?'Resume feed':'Pause feed' }}</button></div>
            <p v-if="feedPaused" class="feed-note" role="status">Message feed paused so you can keep reading. Stage progress still updates.</p>
            <p v-if="flow.reuse" class="feed-note">This run reuses completed work. Earlier messages keep their original timestamps.</p>
            <div v-if="!visibleActivity.length" class="activity-empty"><strong>{{ run.observation?'The chart observations are saved.':'Waiting for the chart reader’s first saved response.' }}</strong><p>{{ run.observation?'Agent messages will appear here as they are saved.':'The reader is checking the uploaded images. There are no agent messages to show yet.' }}</p><details v-if="run.observation"><summary>Read the chart observations</summary><p>{{ run.observation.summary }}</p></details></div>
            <ol v-else class="activity-feed"><li v-for="item in visibleActivity" :key="item.id"><details @toggle="pauseWhileReading($event)"><summary><div class="activity-meta"><strong>{{ item.title }}</strong><time v-if="item.at" :datetime="new Date(item.at).toISOString()">{{ time(item.at) }}{{ item.reused?' · Earlier run':'' }}</time></div><p>{{ item.text }}</p><span class="read-message">Read saved message</span></summary><blockquote>{{ item.text }}</blockquote><p v-if="item.secondary" class="revised-view"><strong>Current view:</strong> {{ item.secondary }}</p></details></li></ol>
            <button v-if="run.opinions?.length||run.trader_dialogue" class="all-discussion" @click="$emit('discussion')">Explore the full discussion<ResearchIcon name="arrow"/></button>
          </section>
          <aside class="next-stage"><h3>{{ flow.complete?'What to do next':flow.stopped?'What happens next':'Up next' }}</h3><strong>{{ flow.complete?'Read the result and both conditional paths':flow.stopped?'Continue the missing work':flow.next?.label||'Your chart assessment' }}</strong><p>{{ flow.complete?'A directional lean and a ready entry are different. Start with the result, then inspect the evidence or discussion if you want more detail.':flow.stopped?'Use the recovery action below. Completed messages and reviews stay saved.':flow.next?.detail||'The page will show the final assessment after it has been saved.' }}</p><div class="return-note"><ResearchIcon name="document"/><p>You can leave this page. Find this run again in <RouterLink to="/saved">Saved analyses</RouterLink>.</p></div><p class="honest-timing">Stages take different amounts of time. The counts show saved work, not a time estimate.</p></aside>
        </div>
      </div>
    </details>
  </section>
</template>

<script setup>
import {computed,ref,watch} from 'vue'
import ResearchIcon from './ResearchIcon.vue'
import {analysisFlow,analysisActivity,durationLabel,connectionState} from '../utils/analysisFlow.mjs'
const props=defineProps({run:{type:Object,required:true},now:{type:Number,default:()=>Date.now()},lastSyncedAt:{type:Number,default:0},pollingIssue:Boolean,compact:Boolean,showActivity:{type:Boolean,default:true}})
defineEmits(['result','discussion'])
const flow=computed(()=>analysisFlow(props.run)),activity=computed(()=>analysisActivity(props.run)),elapsed=computed(()=>durationLabel(props.run,props.now))
const hasPaths=computed(()=>Boolean((props.run.verdict?.action_paths || props.run.verdict?.strategy_scenarios)))
const connection=computed(()=>connectionState(props.run,{lastSyncedAt:props.lastSyncedAt,pollingIssue:props.pollingIssue,now:props.now}))
const feedPaused=ref(false),heldActivity=ref([]),visibleActivity=computed(()=>feedPaused.value?heldActivity.value:activity.value)
const processExpanded=ref(props.run.status!=='complete')
function toggleFeed(){if(!feedPaused.value)heldActivity.value=activity.value;feedPaused.value=!feedPaused.value}
function pauseWhileReading(event){if(event.target.open&&props.run.status==='running'&&!feedPaused.value){heldActivity.value=activity.value;feedPaused.value=true}}
watch(()=>props.run.id,()=>{feedPaused.value=false;heldActivity.value=[];processExpanded.value=props.run.status!=='complete'})
watch(()=>props.run.status,status=>{if(status==='complete'&&!feedPaused.value)processExpanded.value=false})
const stateLabel=value=>({done:'Saved',active:'In progress',pending:'Next',stopped:'Needs attention','not-recorded':'Not recorded'}[value]||value)
const time=value=>new Date(value).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})
const updateLabel=computed(()=>{const at=Date.parse(props.run.updated_at);if(!Number.isFinite(at))return 'Waiting for a saved update.';const seconds=Math.max(0,Math.floor((props.now-at)/1000));return seconds<5?'A progress update was just saved.':seconds<60?`Last saved update ${seconds}s ago.`:`Last saved update ${Math.floor(seconds/60)}m ago.`})
</script>

