.activity-layout.without-activity{grid-template-columns:1fr}.without-activity .next-stage{border-left:0;padding-left:0}
@media(max-width:1000px){.stage-list{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px 0}.stage-list li:nth-child(4){padding-left:0}.activity-layout{grid-template-columns:1fr}.next-stage{border-left:0;padding:20px 0 0;border-top:1px solid var(--research-line)}}
@media(max-width:600px){.analysis-progress{scroll-margin-top:135px}.progress-heading{padding:18px 17px;align-items:flex-start;flex-direction:column;gap:15px}.progress-heading h2{font-size:22px}.progress-explanation{font-size:12px}.current-count{padding:17px 18px 0}.save-status{padding:12px 18px 6px}.process-details>summary{padding:14px 18px}.process-content{padding:18px}.phase-list{grid-template-columns:repeat(2,1fr);gap:16px}.stage-list strong{font-size:10px}.stage-list small{font-size:9px}.stage-list li{padding-bottom:12px}.elapsed{margin-left:6px}.result-button{white-space:normal}}
